rows[126459]={title={{14,995653559},"블링트론 4000"},description={{194,764782634},"무한한 부를 소유한 로봇 블링트론 4000을 조립합니다. 간단히 \"블링\"이라고 불리기를 좋아하는 이 로봇은 자신에게 말을 거는 이에게 무작위 선물을 줍니다. 10분 동안 지속되며, 선물은 하루에 한 번만 받을 수 있습니다."}}
rows[126460]={title={{17,2073959942},"판다렌 봉기"},description={"^increases the target's damage taken by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","대상이 받는 피해가 \0311\031%만큼 증가합니다.",{0},{1}},aura={"^damage taken increased ([%+%-]?%d[%d,.%+%-to –]*)%%%. lao%-fe was a brutal oppressor; but the pandaren monks banded together to overthrow him%.$","받는 피해 \0311\031%만큼 증가\010판다렌 수도사들이 봉기하여 잔인한 압제자 라오페를 타도함",{0},{1}}}
rows[126462]={title={{13,1155937432},"열기 모루"},description={"^places a thermal anvil at your feet, granting anyone nearby the use of both an anvil and a forge%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","열기 모루를 내려놔 근처 모두에게 모루 또는 가열로가 필요한 제작을 가능하게 합니다. \0311\031 동안 지속됩니다.",{1},{1}}}
