rows[126901]={title={{11,1681908511},"필멸의 분쇄"},description={"^tears open an enemy's vital artery, dealing ([%+%-]?%d[%d,.%+%-to –]*) physical damage every ([%+%-]?%d[%d,.%+%-to –]*) sec, and reducing healing taken by ([%+%-]?%d[%d,.%+%-to –]*)%%, for ([%+%-]?%d[%d,.]* %a+)%. stacks%.$","적의 동맥을 뜯어 \0314\031 동안 \0312\031초마다 \0311\031의 물리피해를 입히고, 받는 치유량을 \0313\031%만큼 감소시킵니다. 중첩됩니다.",{0,0,0,1},{1,2,3,4}},aura={"^suffering ([%+%-]?%d[%d,.%+%-to –]*) physical damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. healing received reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","\0312\031초마다 \0311\031의 물리 피해\010받는 치유량 \0313\031%만큼 감소",{0,0,0},{1,2,3}}}
