rows[126912]={title={{14,845916050},"치명적인 소용돌이"},description={"^deals ([%+%-]?%d[%d,.%+%-to –]*) physical damage to enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards, causing them to bleed, suffering ([%+%-]?%d[%d,.%+%-to –]*) physical damage every ([%+%-]?%d[%d,.%+%-to –]*) sec for ([%+%-]?%d[%d,.]* %a+), or until healed above 90%% of maximum health%.$","\0312\031미터 안의 적에게 \0311\031의 물리 피해를 입히며 출혈을 일으킵니다. 대상은 \0315\031 동안 \0314\031초마다 \0313\031의 물리 피해를 입습니다. 대상의 생명력이 최대 생명력의 90% 이상에 도달하면 출혈이 멈춥니다.",{0,0,0,0,1},{1,2,3,4,5}},aura={"^suffering ([%+%-]?%d[%d,.%+%-to –]*) physical damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. effect will dissipate if healed above 90%% of maximum health%.$","\0312\031초마다 \0311\031의 물리 피해\010최대 생명력의 90% 이상까지 치유되면 효과 사라짐",{0,0},{1,2}}}
