rows[128951]={title={{10,1979623359},"냉기의 덫"},description={"^place a frost trap that creates an ice slick around itself for ([%+%-]?%d[%d,.]* %a+) when the first enemy approaches it%. all enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards will be slowed by ([%+%-]?%d[%d,.%+%-to –]*)%% while in the area of effect%. trap will exist for ([%+%-]?%d[%d,.]* %a+)%. only one trap can be active at a time%.$","냉기의 덫을 설치합니다. 적이 다가오면 덫에서 가느다란 얼음실이 퍼져 나와, \0311\031 동안 \0312\031미터 반경 이내 적의 이동 속도를 \0313\031%만큼 감소시킵니다. 덫은 \0311\031 동안 지속되며, 한 개만 놓아둘 수 있습니다.",{1,0,0,1},{1,2,3,1}}}
