rows[129793]={title={{7,558803548},"나른함"},description={"^afflicts an enemy with an overwhelming sense of despair, sapping their will to act and decreasing haste and movement speed by ([%+%-]?%d[%d,.%+%-to –]*)%%%. stacks%.$","압도적인 절망감으로 적을 괴롭히며 행동할 의지를 약화시켜 가속과 이동 속도를 \0311\031%만큼 감소시킵니다. 이 효과는 중첩됩니다.",{0},{1}},aura={"^haste reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%. movement speed reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","가속 \0311\031%만큼 감소\010이동 속도 \0312\031%만큼 감소",{0,0},{1,2}}}
