rows[129861]={title={{14,52758604},"고대 의식"},description={"^give in to your anger for ([%+%-]?%d[%d,.]* %a+)%. while active, the next killing blow made against a player will transform you into a mogu for ([%+%-]?%d[%d,.]* %a+), preventing any actions from being taken while you gloat%.$","\0311\031 동안 분노에 휩싸입니다. 활성화된 동안 다른 플레이어에게 치명적인 공격을 가하면 \0312\031 동안 모구로 변신하여 상대를 조롱합니다. 조롱 중에는 다른 행동을 할 수 없습니다.",{1,1},{1,2}},aura={{21,710143134},"분노에 휩싸임"}}
